function updateOrchardSharePreview(){if(ui.openForm?.type!=='orchard')return;const checkbox=$('#form-sharecropping'),field=$('#owner-share-field'),input=$('#form-ownerSharePercent'),preview=$('#owner-share-preview');if(!checkbox||!field||!input)return;field.hidden=!checkbox.checked;const pct=Number(input.value);if(preview)preview.textContent=checkbox.checked&&Number.isFinite(pct)&&pct>=0&&pct<=100?`Al proprietario ${number(pct,2)}% · A te ${number(100-pct,2)}%. La ripartizione vale anche per le raccolte già registrate.`:'Indica una percentuale valida da 0 a 100.';}
function updateSalePreview(){if(ui.openForm?.type!=='sale')return;const form=$('#entry-form');if(!form)return;const liters=Number(form.elements.namedItem('liters')?.value)||0;const price=Number(form.elements.namedItem('price')?.value)||0;const target=$('#sale-preview b');if(target)target.textContent=money(liters*price);}
async function removeRecord(type,id){if(saveBusy||!desktopReady)return;const keys={orchard:'orchards',harvest:'harvests',sale:'sales',customer:'customers',expense:'expenses',adjustment:'adjustments',payment:'payments'};const key=keys[type],item=db[key]?.find(x=>String(x.id)===String(id));if(!item)return;let extra='';if(type==='orchard'&&(db.harvests.some(h=>String(h.orchardId)===String(id))||db.sales.some(s=>String(s.orchardId)===String(id))||db.expenses.some(x=>String(x.orchardId)===String(id)))){toast('Questo oliveto ha movimenti collegati: non può essere eliminato.','error');return;}if(type==='customer'&&db.sales.some(s=>String(s.customerId)===String(id))){toast('Il cliente ha vendite collegate: non può essere eliminato.','error');return;}if(type==='sale'&&db.payments.some(p=>String(p.saleId)===String(id)))extra=' Verranno eliminati anche i pagamenti collegati.';if(!confirm('Eliminare definitivamente questa registrazione?'+extra))return;const previous=JSON.stringify(db);db[key]=db[key].filter(x=>String(x.id)!==String(id));if(type==='sale')db.payments=db.payments.filter(p=>String(p.saleId)!==String(id));if(['harvest','sale','adjustment'].includes(type)&&allYears().some(y=>stockYear(y)<-.001)){db=JSON.parse(previous);toast('Non puoi eliminarla: il magazzino diventerebbe negativo.','error');return;}if(!await commit(previous)){db=JSON.parse(previous);return;}toast('Registrazione eliminata.');}
